insert into public.crm_vendor_products (vendor_id, category, product, specs, moq, lead_time, last_price)
select ven.id, ven.category, ven.supplier, ven.products_specs, ven.moq, ven.lead_time, ven.last_price
from public.crm_vendors ven
where coalesce(ven.products_specs, '') <> ''
  and not exists (select 1 from public.crm_vendor_products p where p.vendor_id = ven.id);

insert into public.crm_vendor_products (vendor_id, category, product, specs, moq, lead_time, last_price)
select ven.id, ven.directory_category, ven.core_products, ven.core_products, ven.moq, ven.lead_time, ven.last_price
from public.crm_vendors ven
where coalesce(ven.core_products, '') <> ''
  and position(ven.core_products in coalesce(ven.products_specs, '')) = 0
  and not exists (
    select 1 from public.crm_vendor_products p
    where p.vendor_id = ven.id and p.product = ven.core_products
  );

