update public.crm_vendor_customers vc
set company_id = match.company_id
from (
  select vc2.id as customer_row, min(co.id) as company_id
  from public.crm_vendor_customers vc2
  join public.crm_companies co
    on lower(btrim(co.name)) = lower(btrim(vc2.customer_name))
   and co.kind is distinct from 'vendor'
  group by vc2.id
  having count(*) = 1
) match
where vc.id = match.customer_row
  and vc.company_id is null;

