update public.crm_vendor_changes ch
set vendor_id = match.vendor_id
from (
  select ch2.id as change_id, min(ven.id) as vendor_id
  from public.crm_vendor_changes ch2
  join public.crm_vendors ven on lower(ven.supplier) = lower(ch2.supplier)
  group by ch2.id
  having count(distinct ven.id) = 1
) match
where ch.id = match.change_id and ch.vendor_id is null;

-- Open quotes are from the vendor page snapshot (Nov 5), not a spreadsheet tab.
insert into public.crm_vendor_quotes (customer_name, item, vendor_name, note, note_tone, vendor_id)
select q.customer_name, q.item, q.vendor_name, q.note, q.note_tone, ven.id
from (values
('Quality Tape', '48x60 2 mil top sheeting on a roll', 'Versa-Pak', null, null),
('Quality Tape', 'Clear poly sheets, 24 x 1024 and 24 x 1200', 'Shadow Plastics', null, null),
('Palmer Hamilton', 'Poly strapping', 'USA Strapping', null, null),
('Palmer Hamilton', 'Pallet bands', 'USA Strapping', null, null),
('Palmer Hamilton', 'Strap seals', 'USA Strapping', null, null),
('Palmer Hamilton', '40x48 chip pads', 'Apex Media LLC', 'Marketing vendor; needs a real supplier', 'danger'),
('Palmer Hamilton', '60x60 chip pads', 'Apex Media LLC', 'Marketing vendor; needs a real supplier', 'danger'),
('Palmer Hamilton', 'Packing tape', 'Apex Media LLC', 'No tape supplier on file', 'danger'),
('Palmer Hamilton', 'Corner and edge protectors (2 lines)', null, 'No vendor set', 'warning')
) as q(customer_name, item, vendor_name, note, note_tone)
left join public.crm_vendors ven
  on lower(ven.supplier) = lower(q.vendor_name)
 and ven.directory_category is not null
where not exists (select 1 from public.crm_vendor_quotes);

